<!doctype html><html lang="en"><head><meta charset="utf-8"><style>
@page { margin: 72px 44px 54px; } * { box-sizing: border-box; } body { margin: 0; color: #1e3028; font-family: DejaVu Sans, sans-serif; font-size: 10px; line-height: 1.6; } header { position: fixed; top: -52px; left: 0; right: 0; height: 38px; border-bottom: 2px solid #15975e; } .brand { float: left; color: #117a4d; font-size: 16px; font-weight: bold; } .brand img { width: 27px; height: 27px; margin-right: 7px; vertical-align: middle; object-fit: contain; } .brand span { vertical-align: middle; } .org { float: right; color: #718078; font-size: 8px; text-align: right; } footer { position: fixed; bottom: -35px; left: 0; right: 0; padding-top: 8px; border-top: 1px solid #dfe8e3; color: #7b8982; font-size: 7px; } footer span { float: right; } footer span:after { content: counter(page); } .eyebrow { color: #7542d6; font-size: 8px; font-weight: bold; text-transform: uppercase; } h1 { margin: 5px 0 8px; font-size: 23px; line-height: 1.25; } .badges span { display: inline-block; margin: 0 5px 13px 0; padding: 4px 8px; border-radius: 11px; color: #116f46; background: #e7f7ee; font-size: 7px; text-transform: uppercase; } .route { width: 100%; margin: 10px 0 19px; border-collapse: collapse; } .route td { width: 50%; padding: 11px; border: 1px solid #dfe8e3; } .route small { display: block; color: #7d8983; font-size: 7px; text-transform: uppercase; } .route strong { font-size: 10px; } .summary { padding: 12px 14px; border-left: 3px solid #7542d6; color: #4c5e55; background: #faf8ff; } .body { margin-top: 19px; white-space: pre-line; } .period { margin-top: 22px; padding-top: 10px; border-top: 1px solid #e1e8e4; color: #75837c; font-size: 8px; } .attachments { width: 100%; margin-top: 20px; border-collapse: collapse; } .attachments caption { padding: 0 0 7px; color: #24372d; font-size: 10px; font-weight: bold; text-align: left; } .attachments th { padding: 7px; color: #fff; background: #263d32; font-size: 7px; text-align: left; text-transform: uppercase; } .attachments td { padding: 7px; border-bottom: 1px solid #e2eae6; color: #405148; font-size: 8px; }
</style></head><body><header><div class="brand"><img src="{{ public_path('assets/brand/charge-trackr-logo.png') }}" alt=""><span>ChargeTrackr</span></div><div class="org">{{ $report->organization?->name }}<br>{{ now()->format('d M Y, H:i') }}</div></header><footer>Internal organization report<span>Page </span></footer><main><div class="eyebrow">{{ str_replace('_', ' ', $report->category) }} report</div><h1>{{ $report->title }}</h1><div class="badges"><span>{{ $report->priority }}</span><span>{{ $report->status }}</span></div><table class="route"><tr><td><small>From</small><strong>{{ $report->sender?->name }}</strong><br>{{ $report->sender?->email }}</td><td><small>To</small><strong>{{ $report->recipient?->name ?? 'Draft - no recipient' }}</strong><br>{{ $report->recipient?->email }}</td></tr></table>@if($report->summary)<div class="summary">{{ $report->summary }}</div>@endif<div class="body">{!! nl2br(e($report->body)) !!}</div>@if($report->period_start || $report->period_end)<div class="period">Reporting period: {{ $report->period_start?->format('d M Y') ?? 'Open' }} to {{ $report->period_end?->format('d M Y') ?? 'Open' }}</div>@endif @if($report->documents->isNotEmpty())<table class="attachments"><caption>Supporting files ({{ $report->documents->count() }})</caption><thead><tr><th>Title</th><th>File</th><th>Size</th><th>Integrity reference</th></tr></thead><tbody>@foreach($report->documents as $document)<tr><td>{{ $document->title }}</td><td>{{ $document->original_name }}</td><td>{{ number_format($document->size_bytes / 1024, 1) }} KB</td><td>{{ substr($document->checksum_sha256, 0, 16) }}</td></tr>@endforeach</tbody></table>@endif</main></body></html>
